import QtQuick
import Quickshell

// 1. EL CONTENEDOR LAYER-SHELL (Convierte la ventana en una Barra/Fondo)
PanelWindow {
    id: marcoPrincipal
    color: "transparent" // Vuelve invisible el fondo de la ventana

    // Al anclar los 4 lados a 'true', le decimos a Hyprland que 
    // estire esta "barra" por toda la pantalla de forma fija.
    anchors {
        top: true
        bottom: true
        left: true
        right: true
    }

    // 2. EL DIBUJO GEOMÉTRICO (Sin muescas)
    Canvas {
        anchors.fill: parent

        // Tus medidas personalizables
        property int leftBarWidth: 100    // Grosor de tu barra izquierda
        property int borderWidth: 10      // Grosor del borde superior, derecho e inferior
        property int radius: 15           // Curvatura de las esquinas internas
        property color themeColor: "#8cf0c3" 

        onWidthChanged: requestPaint()
        onHeightChanged: requestPaint()

        onPaint: {
            var ctx = getContext("2d");
            ctx.reset();

            var w = width;
            var h = height;
            var barW = leftBarWidth;
            var b = borderWidth;
            var r = radius;

            ctx.beginPath();
            ctx.fillStyle = themeColor;

            // ========================================================
            // A. LÍMITES EXTERIORES (Sentido Horario)
            // ========================================================
            ctx.moveTo(0, 0);
            ctx.lineTo(w, 0);
            ctx.lineTo(w, h);
            ctx.lineTo(0, h);
            ctx.closePath();

            // ========================================================
            // B. EL HUECO CENTRAL LIMPIO (Sentido Anti-Horario)
            // ========================================================

            // Empezamos en la esquina superior izquierda del hueco libre
            ctx.moveTo(barW, b + r);

            // Borde Izquierdo interno (bajamos paralelo a la barra gruesa)
            ctx.lineTo(barW, h - b - r);
            ctx.arcTo(barW, h - b, barW + r, h - b, r);

            // Borde Inferior interno (vamos hacia la derecha)
            ctx.lineTo(w - b - r, h - b);
            ctx.arcTo(w - b, h - b, w - b, h - b - r, r);

            // Borde Derecho interno (subimos paralelo al margen delgado)
            ctx.lineTo(w - b, b + r);
            ctx.arcTo(w - b, b, w - b - r, b, r);

            // Borde Superior interno (volvemos hacia la izquierda)
            ctx.lineTo(barW + r, b);
            ctx.arcTo(barW, b, barW, b + r, r);

            // Ejecutamos el corte
            ctx.fill();
        }
    }
}

import QtQuick

Canvas {
    id: root
    anchors.fill: parent

    // ==========================================
    // 📐 PROPIEDADES DEL MARCO ASIMÉTRICO
    // ==========================================
    property int leftBarWidth: 100    // Grosor de tu barra lateral izquierda
    property int borderWidth: 10      // Grosor de la línea en el techo, derecha y suelo
    property int notchWidth: 180      // Ancho de las muescas superior, derecha e inferior
    property int notchDepth: 25       // Profundidad de las muescas hacia el centro
    property int radius: 15           // Curvatura de todas las esquinas
    property color color: "#8cf0c3"   // El verde de tu tema anterior

    // Reactividad: Si la pantalla o las variables cambian, redibujar
    onWidthChanged: requestPaint()
    onHeightChanged: requestPaint()

    onPaint: {
        var ctx = getContext("2d");
        ctx.reset();

        // Variables cortas para no escribir tanto en las fórmulas matemáticas
        var w = width;
        var h = height;
        var barW = leftBarWidth;
        var b = borderWidth;
        var r = radius;
        var nW = notchWidth;
        var nD = notchDepth;

        // Calculamos el punto medio exacto del "área libre" (sin contar la barra izquierda)
        var cX = barW + ((w - barW) / 2); 
        var cY = h / 2;                 

        ctx.beginPath();
        ctx.fillStyle = root.color;

        // ========================================================
        // 1. LÍMITES EXTERIORES (Sentido Horario)
        // Cubrimos toda la pantalla de esquina a esquina
        // ========================================================
        ctx.moveTo(0, 0);
        ctx.lineTo(w, 0);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h);
        ctx.lineTo(0, 0);

        // ========================================================
        // 2. EL HUECO CENTRAL (Sentido Anti-Horario)
        // Aquí "esculpimos" el interior de la pantalla y las muescas
        // ========================================================

        // Empezamos en la esquina superior izquierda del área libre
        ctx.moveTo(barW, b + r);

        // 👉 A. BORDE IZQUIERDO (Bajamos pegados a la barra principal)
        ctx.lineTo(barW, h - b - r);
        ctx.arcTo(barW, h - b, barW + r, h - b, r);

        // 👉 B. SUELO Y MUESCA INFERIOR (Nos movemos hacia la derecha)
        ctx.lineTo(cX - nW/2 - r, h - b);
        ctx.arcTo(cX - nW/2, h - b, cX - nW/2, h - b - nD, r); // Curva subiendo
        ctx.lineTo(cX - nW/2, h - b - nD + r);
        ctx.arcTo(cX - nW/2, h - b - nD, cX - nW/2 + r, h - b - nD, r); // Techo de muesca
        ctx.lineTo(cX + nW/2 - r, h - b - nD);
        ctx.arcTo(cX + nW/2, h - b - nD, cX + nW/2, h - b - nD + r, r); // Curva bajando
        ctx.lineTo(cX + nW/2, h - b - r);
        ctx.arcTo(cX + nW/2, h - b, cX + nW/2 + r, h - b, r); // Vuelta al suelo

        ctx.lineTo(w - b - r, h - b);
        ctx.arcTo(w - b, h - b, w - b, h - b - r, r);

        // 👉 C. BORDE DERECHO Y SU MUESCA (Subimos hacia el techo)
        ctx.lineTo(w - b, cY + nW/2 + r);
        ctx.arcTo(w - b, cY + nW/2, w - b - nD, cY + nW/2, r); // Entramos a la izquierda
        ctx.lineTo(w - b - nD + r, cY + nW/2);
        ctx.arcTo(w - b - nD, cY + nW/2, w - b - nD, cY + nW/2 - r, r); // Pared de muesca
        ctx.lineTo(w - b - nD, cY - nW/2 + r);
        ctx.arcTo(w - b - nD, cY - nW/2, w - b - nD + r, cY - nW/2, r); // Salimos a la derecha
        ctx.lineTo(w - b - r, cY - nW/2);
        ctx.arcTo(w - b, cY - nW/2, w - b, cY - nW/2 - r, r); // Vuelta al borde derecho

        ctx.lineTo(w - b, b + r);
        ctx.arcTo(w - b, b, w - b - r, b, r);

        // 👉 D. TECHO Y MUESCA SUPERIOR (Nos movemos hacia la izquierda)
        ctx.lineTo(cX + nW/2 + r, b);
        ctx.arcTo(cX + nW/2, b, cX + nW/2, b + nD, r); // Bajamos
        ctx.lineTo(cX + nW/2, b + nD - r);
        ctx.arcTo(cX + nW/2, b + nD, cX + nW/2 - r, b + nD, r); // Suelo de muesca
        ctx.lineTo(cX - nW/2 + r, b + nD);
        ctx.arcTo(cX - nW/2, b + nD, cX - nW/2, b + nD - r, r); // Subimos
        ctx.lineTo(cX - nW/2, b + r);
        ctx.arcTo(cX - nW/2, b, cX - nW/2 - r, b, r); // Vuelta al techo

        ctx.lineTo(barW + r, b);
        ctx.arcTo(barW, b, barW, b + r, r);

        // Cerramos el circuito geométrico y rellenamos la pintura
        ctx.closePath(); 
        ctx.fill();
    }
}

import QtQuick
import "../"

Canvas {
    id: root
    anchors.fill: parent

    // These are set by TopBar.qml with the real clamped widths.
    // They default to the Theme constraints so the shape is never empty.
    property int leftWidth:   Theme.lNotchMinWidth
    property int centerWidth: Theme.cNotchMinWidth
    property int rightWidth:  Theme.rNotchMinWidth

    property int notchHeight:     Theme.notchHeight
    property int radius:          Theme.notchRadius
    property int topBorderWidth:  Theme.borderWidth
    property color color:         Theme.background

    onWidthChanged:       requestPaint()
    onHeightChanged:      requestPaint()
    onLeftWidthChanged:   requestPaint()
    onCenterWidthChanged: requestPaint()
    onRightWidthChanged:  requestPaint()
    onColorChanged:       requestPaint()

    onPaint: {
        var ctx = getContext("2d");
        ctx.reset();

        var leftW   = root.leftWidth
        var centerW = root.centerWidth
        var rightW  = root.rightWidth

        var r = root.radius
        var h = root.notchHeight
        var b = root.topBorderWidth
        var w = width

        // Calculated positions
        var centerStart = (w / 2) - (centerW / 2)
        var centerEnd   = (w / 2) + (centerW / 2)
        var rightStart  = w - rightW

        ctx.beginPath();
        ctx.fillStyle = root.color;

        // ============================
        // 1. LEFT NOTCH
        // ============================
        ctx.moveTo(0, h);
        ctx.lineTo(leftW - r, h);
        ctx.arcTo(leftW, h, leftW, h - r, r);
        ctx.lineTo(leftW, b + r);
        ctx.arcTo(leftW, b, leftW + r, b, r);

        // ============================
        // 2. GAP 1 (Left → Center)
        // ============================
        ctx.lineTo(centerStart - r, b);

        // ============================
        // 3. CENTER NOTCH
        // ============================
        ctx.arcTo(centerStart, b, centerStart, b + r, r);
        ctx.lineTo(centerStart, h - r);
        ctx.arcTo(centerStart, h, centerStart + r, h, r);
        ctx.lineTo(centerEnd - r, h);
        ctx.arcTo(centerEnd, h, centerEnd, h - r, r);
        ctx.lineTo(centerEnd, b + r);
        ctx.arcTo(centerEnd, b, centerEnd + r, b, r);

        // ============================
        // 4. GAP 2 (Center → Right)
        // ============================
        ctx.lineTo(rightStart - r, b);

        // ============================
        // 5. RIGHT NOTCH
        // ============================
        ctx.arcTo(rightStart, b, rightStart, b + r, r);
        ctx.lineTo(rightStart, h - r);
        ctx.arcTo(rightStart, h, rightStart + r, h, r);
        ctx.lineTo(w, h);

        // ============================
        // 6. CLOSE LOOP
        // ============================
        ctx.lineTo(w, 0);
        ctx.lineTo(0, 0);
        ctx.lineTo(0, h);

        ctx.fill();
    }
}

